const mode = String(params.mode || 'check_status').trim().toLowerCase();

let hasUltralytics = false;
let ultralyticsVersion = 'none';

try {
  const checkRes = await shell.runPython(`
try:
    import ultralytics
    print("STATUS_INSTALLED:" + getattr(ultralytics, "__version__", "unknown"))
except Exception as e:
    print("STATUS_NOT_INSTALLED:" + str(e))
`);
  if (checkRes.stdout.includes('STATUS_INSTALLED:')) {
    hasUltralytics = true;
    ultralyticsVersion = checkRes.stdout.split('STATUS_INSTALLED:')[1].trim();
  }
} catch (e) {}

let actionOutput = '';
if (mode === 'install_ultralytics' || mode === 'reinstall_fresh') {
  try {
    const cmd = mode === 'reinstall_fresh' ? 'pip install --upgrade --force-reinstall ultralytics' : 'pip install ultralytics';
    const installRes = await shell.exec(cmd, 180000);
    actionOutput = installRes.stdout || installRes.stderr || 'Installation completed.';
    hasUltralytics = true;
  } catch (err) {
    actionOutput = 'Installation failed or timed out: ' + (err.message || String(err));
  }
}

const statusColor = hasUltralytics ? '#10b981' : '#f59e0b';
const statusText = hasUltralytics ? `Installed (v${ultralyticsVersion})` : 'Not Installed (Edge CV Mode active)';

const cardHtml = `
  <div class="plugin-custom-card" style="border: 1px solid ${statusColor}; padding: 14px 16px; border-radius: 10px; gap: 10px;">
    <div style="display: flex; align-items: center; justify-content: space-between;">
      <div style="font-weight: 700; font-size: 13px; color: var(--text-main); display: flex; align-items: center; gap: 6px;">
        ⚙️ YOLO26 Python Environment Status
      </div>
      <span style="font-size: 11px; padding: 2px 8px; border-radius: 12px; background: rgba(0,0,0,0.3); color: ${statusColor}; font-weight: 600;">
        ${statusText}
      </span>
    </div>
    <div style="font-size: 11.5px; color: var(--text-dim); line-height: 1.5;">
      OpenCV, Pillow, and NumPy are actively loaded for zero-dependency real-time edge detections.
      Ultralytics PyTorch package enables download of pretrained YOLO26n / YOLO26s .pt model weights directly from the official hub.
    </div>
    ${actionOutput ? `<div style="font-size: 10.5px; font-family: monospace; background: rgba(0,0,0,0.4); padding: 8px; border-radius: 6px; max-height: 120px; overflow-y: auto; color: var(--text-muted); white-space: pre-wrap;">${actionOutput}</div>` : ''}
  </div>
`;

return {
  ui_type: 'card',
  html: cardHtml,
  has_ultralytics: hasUltralytics,
  version: ultralyticsVersion,
  mode: mode,
  log: actionOutput
};
